import base64,hashlib,io,json,os,sys,zipfile
from pathlib import Path
for key in ('OMP_NUM_THREADS','OPENBLAS_NUM_THREADS','MKL_NUM_THREADS','NUMEXPR_NUM_THREADS'):os.environ[key]='1'
raw=base64.b64decode('');assert hashlib.sha256(raw).hexdigest()=='16611a4257f2a6a9be32fc2ebe85c848d03710f81cda9753bfc35522cf5c7dd6'
root=Path('/root/r14_code_v1');root.mkdir()
with zipfile.ZipFile(io.BytesIO(raw)) as z:
    for r in json.loads(z.read('source_manifest.json')):
        p=(root/r['path']).resolve();assert p.is_relative_to(root)
        data=z.read(r['path']);assert len(data)==r['bytes'] and hashlib.sha256(data).hexdigest()==r['sha256']
        p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(data)
sys.path.insert(0,str(root))
from hutter_research.cpu_round14_native_confirmation import main
if __name__=='__main__':main('a')
